import java.sql.*;import java.util.*;import model.InvestigationTask;
public final class InvestigationTaskDao {
 public List<InvestigationTask> findByCaseId(String caseId)throws SQLException{List<InvestigationTask> out=new ArrayList<>();String sql="SELECT t.*,o.name officer_name FROM investigation_tasks t LEFT JOIN officers o ON o.id=t.assigned_to WHERE t.case_id=? ORDER BY CASE t.priority WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 ELSE 4 END, CASE t.status WHEN 'COMPLETED' THEN 5 WHEN 'CANCELLED' THEN 6 ELSE 1 END, t.due_date, t.id";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,caseId);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new InvestigationTask(r.getLong("id"),caseId,r.getString("title"),r.getString("description"),r.getString("assigned_to"),r.getString("officer_name"),r.getString("priority"),r.getString("status"),r.getString("due_date"),r.getString("completed_at")));}}return out;}
 public long create(String caseId,String title,String description,String assignedTo,String priority,String dueDate,String createdBy)throws SQLException{String sql="INSERT INTO investigation_tasks(case_id,title,description,assigned_to,priority,status,due_date,created_by) VALUES(?,?,?,?,?,'PENDING',?,?)";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){p.setString(1,caseId);p.setString(2,title);p.setString(3,description);p.setString(4,assignedTo);p.setString(5,priority);p.setString(6,dueDate);p.setString(7,createdBy);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return r.next()?r.getLong(1):0;}}}
 public void updateStatus(long id,String status)throws SQLException{String completed="COMPLETED".equals(status)?"CURRENT_TIMESTAMP": "NULL";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE investigation_tasks SET status=?,completed_at="+completed+",updated_at=CURRENT_TIMESTAMP WHERE id=?")){p.setString(1,status);p.setLong(2,id);if(p.executeUpdate()!=1)throw new SQLException("Task not found");}}
}
